from fractions import Fraction


def rigidity_lower_bound(a: int, b: int, p: int, q: int) -> Fraction:
    """|a + b*(p/q)| = |a*q + b*p| / q; Theorem 1 says this is >= 1/q
    whenever the integer numerator a*q + b*p is nonzero."""
    if q <= 0:
        raise ValueError("denominator must be positive")
    numerator: int = a * q + b * p
    if numerator == 0:
        raise ValueError("a + b*x = 0 is excluded by hypothesis (i)")
    return Fraction(abs(numerator), q)


def main() -> None:
    p, q = 22, 7
    for a, b in [(0, 1), (-3, 1), (3, -1), (1, 1)]:
        val = rigidity_lower_bound(a, b, p, q)
        print(a, b, val, float(val), val >= Fraction(1, q))


if __name__ == "__main__":
    main()

from decimal import Decimal, getcontext
from fractions import Fraction
from typing import Iterator

getcontext().prec = 60


def convergents_of(x: Fraction, n_terms: int) -> Iterator[Fraction]:
    p2, p1, q2, q1 = 0, 1, 1, 0
    frac = x
    for _ in range(n_terms):
        a = frac.numerator // frac.denominator
        p2, p1 = p1, a * p1 + p2
        q2, q1 = q1, a * q1 + q2
        yield Fraction(p1, q1)
        rem = frac - a
        if rem == 0:
            break
        frac = 1 / rem


def good_approx(x: Fraction, threshold: int) -> Fraction:
    for cand in convergents_of(x, 80):
        d = cand.denominator
        if d >= threshold and abs(x - cand) < Fraction(1, d ** 2):
            return cand
    raise RuntimeError("no suitable convergent")


def main() -> None:
    x = Fraction(Decimal(3).sqrt())
    for n in range(8):
        q = good_approx(x, n + 1)
        a, b = -q.numerator, q.denominator
        print(n, a, b, float(abs(a + b * x)), 1 / (n + 1))


if __name__ == "__main__":
    main()

