function DIRICHLET_DEN_GE(x, N):
    for (p, q) in convergents(x):
        if q >= N and |x - p/q| < 1/q^2:
            return p/q
    fail

function FORMS_TO_ZERO(x, T):
    for n in 0 .. T-1:
        c/d <- DIRICHLET_DEN_GE(x, n+1)
        emit (-c, d, -c + d*x)   // |-c + d*x| < 1/d <= 1/(n+1)
